"""
Password registration and login verification helpers.

Policy:
- New password hashes use Argon2id with parameters meeting the current OWASP Password Storage
  Cheat Sheet guidance.
- Login verification supports any previously-used supported format (legacy verification allowed).
"""

from __future__ import annotations

import argon2_hasher
import pbkdf2_hasher
import scrypt_hasher
import bcrypt_hasher


def register_password(password: str) -> str:
    """
    Return the string to store for a newly registered user's password.

    New hashes must follow the current OWASP Password Storage Cheat Sheet.
    In this deployment, Argon2id is used for new hashes.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if password == "":
        raise ValueError("password must not be empty")

    # Argon2id hashing (argon2-cffi). The skill module already pins compliant parameters.
    return argon2_hasher.hash_argon2(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against a stored password hash.

    Supports hashes produced by register_password (Argon2id) and legacy supported formats:
    - $pbkdf2-...$
    - $argon2id/argon2...$
    - $scrypt$...
    - $2a$/$2b$/$2y$ (bcrypt)
    """
    if not isinstance(stored, str):
        return False

    if stored.startswith("$pbkdf2-"):
        return pbkdf2_hasher.verify_pbkdf2(password, stored)

    if stored.startswith("$argon2"):
        return argon2_hasher.verify_argon2(password, stored)

    if stored.startswith("$scrypt$"):
        return scrypt_hasher.verify_scrypt(password, stored)

    if stored.startswith(("$2a$", "$2b$", "$2y$")):
        return bcrypt_hasher.verify_bcrypt(password, stored)

    return False
